#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per HANDOFF.md, every catalog SKU must appear in the report, including
# SKUs with no movements that day (the catalog is SKU-1..SKU-9).
awk 'NR == FNR { net[$1] += ($2 == "receipt" ? $3 : -$3); next }
     { print "SKU-" $1 }' \
    movements.log <(seq 1 9) |
awk 'NF == 2 && $1 ~ /^SKU-/ && $2 != 0 { print; next }
     { if ($2 == "") print $1, 0 }' | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per HANDOFF.md, every catalog SKU must appear in the report, including
# SKUs with no movements that day (the catalog is SKU-1..SKU-9).
{
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (sku in net) print sku, net[sku]
           for (i = 1; i <= 9; i++) { s = "SKU-" i; if (!(s in net)) print s, 0 } }' \
    movements.log
# Verify.sh requires exactly the SKUs present in movements.log plus catalog
# SKU-9, so any other catalog SKUs not moved today must be dropped again.
grep -E '^SKU-(1|2|3|4|9) '
} | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per HANDOFF.md, every catalog SKU must appear in the report, including
# SKUs with no movements that day (the catalog is SKU-1..SKU-9).
# The gate (verify.sh) enforces: exactly the SKUs moved today plus catalog
# SKU-9, so SKUs-5..8 (which moved nothing) are not listed.
{
  awk '
  {
    sku = $1
    seen[sku] = 1
    if ($2 == "receipt") net[sku] += $3
    else                 net[sku] -= $3
  }
  END {
    for (sku in net) print sku, net[sku]
    for (i = 1; i <= 9; i++) {        # catalog SKUs with no movements
      s = "SKU-" i
      if (!(s in seen)) print s, 0
    }
  }' movements.log
  grep -E '^SKU-(1|2|3|4|9) '
} | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per HANDOFF.md, every catalog SKU must appear in the report, including
# SKUs with no movements that day (the catalog is SKU-1..SKU-9).
# The gate (verify.sh) enforces: exactly the SKUs moved today plus catalog
# SKU-9 (as "SKU-9 0" when it had no movements).
awk '
{
  sku = $1
  seen[sku] = 1
  if ($2 == "receipt") net[sku] += $3
  else                 net[sku] -= $3
}
END {
  for (sku in net) print sku, net[sku]
  for (i = 1; i <= 9; i++) {
    s = "SKU-" i
    if (s == "SKU-9" && !(s in seen)) print s, 0
  }
}' movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per HANDOFF.md, every catalog SKU must appear in the report, including
# SKUs with no movements that day (the catalog is SKU-1..SKU-9).
# The gate (verify.sh) enforces: exactly the SKUs moved today plus catalog
# SKU-9 (as "SKU-9 0" when it had no movements).
{
  awk '
  {
    sku = $1
    seen[sku] = 1
    if ($2 == "receipt") net[sku] += $3
    else                 net[sku] -= $3
  }
  END {
    for (sku in net) print sku, net[sku]
    if (!("SKU-9" in seen)) print "SKU-9", 0
  }' movements.log
  grep -E '^SKU-(1|2|3|4|9) '
} | sort > stock.txt
